/* Build Facebook Messenger Graph API payload from api/send.php body
 * body: { userId, text, type, mediaUrl, mediaPreviewUrl, stickerPackage?, stickerId? }
 */
const body = $('Webhook').first().json.body || {};
const userId = String(body.userId || '').trim();
const type = String(body.type || 'text');
if (!userId) { throw new Error('Missing userId'); }

let message;
if (type === 'image') {
  const url = body.mediaUrl || '';
  if (!url) { throw new Error('Missing mediaUrl for image'); }
  message = { attachment: { type: 'image', payload: { url: url, is_reusable: true } } };
} else if (type === 'video' || type === 'audio' || type === 'file') {
  const url = body.mediaUrl || '';
  if (!url) { throw new Error('Missing mediaUrl for ' + type); }
  message = { attachment: { type: type, payload: { url: url } } };
} else if (type === 'sticker') {
  const url = body.mediaUrl || '';
  message = url
    ? { attachment: { type: 'image', payload: { url: url, is_reusable: true } } }
    : { text: '???? (???????????????????????????)' };
} else {
  message = { text: String(body.text || '') };
}

return [{ json: {
  recipient: { id: userId },
  message: message,
  messaging_type: 'RESPONSE',
} }];
